#!/usr/bin/env bash
# Regenerate THIRD_PARTY.md at the repository root:
#   header + packaging/third-party/bundled.md (hand-written: bundled programs, fonts, models)
#   + the Rust crate list and licence texts from cargo-about (about.toml / about.hbs).
# Needs: cargo install cargo-about --locked --features cli
# Usage: bash packaging/third-party/generate.sh [--check]   (--check: fail if the file is stale)
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
HERE="$ROOT/packaging/third-party"
OUT="$ROOT/THIRD_PARTY.md"
cd "$ROOT"

command -v cargo-about >/dev/null || { echo "cargo-about missing: cargo install cargo-about --locked --features cli" >&2; exit 1; }
tmp="$(mktemp)"; crates="$(mktemp)"
trap 'rm -f "$tmp" "$crates"' EXIT

# Default features = what ships (castor-app's `demo-tools` / `shots` are dev-only).
cargo about generate --config "$HERE/about.toml" --manifest-path "$ROOT/Cargo.toml" --workspace \
  --locked --fail -o "$crates" "$HERE/about.hbs"

# Castor's own crates are covered by the main licence: drop their rows from the table.
own="$(sed -n 's/^name *= *"\(.*\)"/\1/p' "$ROOT"/crates/*/Cargo.toml | paste -sd'|' -)"
grep -v -E "^\| \[($own)\]\(" "$crates" > "$crates.f" && mv "$crates.f" "$crates"

version="$(awk '/^\[workspace\.package\]/{p=1;next} /^\[/{p=0} p && /^version *=/{gsub(/[" ]/,"",$0); split($0,a,"="); print a[2]; exit}' Cargo.toml)"
{
  echo "# Third-party notices"
  echo
  echo "Castor $version — © basedpolymer — GPL-3.0-or-later. This file lists the third-party"
  echo "software and data that Castor contains, bundles or downloads, with their licences."
  echo "It is generated by \`packaging/third-party/generate.sh\`; edit"
  echo "\`packaging/third-party/bundled.md\` for the hand-written part."
  echo
  cat "$HERE/bundled.md"
  echo
  cat "$crates"
} > "$tmp"

if [ "${1:-}" = "--check" ]; then
  cmp -s "$tmp" "$OUT" || { echo "THIRD_PARTY.md is out of date: run packaging/third-party/generate.sh" >&2; exit 1; }
  echo "THIRD_PARTY.md is up to date"
else
  mv "$tmp" "$OUT"; trap 'rm -f "$crates"' EXIT
  echo "wrote $OUT ($(wc -c < "$OUT") bytes, $(grep -c '^| \[' "$OUT") crates)"
fi
